--- from: Assets/BundleResources/Prefabs/Activity/WebJumpPanel12000301.prefab > name: WebJumpPanel12000301
---@class UIActivitySkipUrlNode
---@field Env                           	UIActivitySkipUrlNode                   
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field BtnLeavefor                   	UnityEngine.RectTransform
---@field DetailText                    	UnityEngine.RectTransform               
---@field TextLeavefor                  	UnityEngine.RectTransform
---@field RewardGroup                   	UnityEngine.RectTransform
---@field CommonGoodsList               	UnityEngine.RectTransform
---@field Text                          	UnityEngine.RectTransform
---@field TextTitle                     	UnityEngine.RectTransform
local UIActivitySkipUrlNode = Class('UIActivitySkipUrlNode')

function UIActivitySkipUrlNode:__init()
    self._data = {}
    self._surveyDojo = nil        --问卷内容
end

function UIActivitySkipUrlNode:__delete()
    if self.co  then
        cs_coroutine.stop(self.co)
        self.co = nil 
    end
    self._data = nil
    self._surveyDojo = nil        --问卷内容
end

function UIActivitySkipUrlNode:Awake()
    SetButtonAction(self.BtnLeavefor, Bind(self, self.OnClick))

    KTool.SetActive(self.BossDrawingNode.gameObject , false)
end

function UIActivitySkipUrlNode:Refresh(data)
    if not data then
        return
    end
    self._data = data
    CfUtils.FillText(self.DetailText , self._data.detail)
    self:FillSelf()
    self:RefreshContent()
    self:RefreshCurrencyBarInfo()
end

function UIActivitySkipUrlNode:RefreshCurrencyBarInfo()
    ActivityUtils.RefreshNavigatorGoods()
end

function UIActivitySkipUrlNode:FillSelf()
    local startTime = self._data.startTime
    local closeTime = self._data.closeTime
    CfUtils.FillText(self.Text, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    CfUtils.FillText(self.TextTitle, self._data.name)
    local redPoint =  self.BtnLeavefor.transform:Find("redPoint")
    CfUtils.SetActive(redPoint, checkNumber(self._data.redDotHint) == 0)
end

--刷新内容
function UIActivitySkipUrlNode:RefreshContent()
    GameUtils.Request(Interfaces.WebLink, {activityUuid = self._data.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
    
        local jsonData = response.data
        local dojo = ActivitySurveyDojo.New()
        dojo:Fill(jsonData)
        self._surveyDojo = dojo
        if checkInt(self._surveyDojo.submitted) == 0 then
           local open =  CfUtils.GetLocalData("WebLink" .. self._data.id , "0")
           -- 标识未打开
           local redPoint =  self.BtnLeavefor.transform:Find("redPoint")
           if checkInt(open) == 0 then
               KTool.SetActive(redPoint, true)
               ActivityUtils.UpdateActivityMainRedPointState(self._data.id, checkNumber(open) == 0 and 0 or -1)
           else 
                if checkInt(self._surveyDojo.canDraw) > 0 then
                    self:DrawReards()    
                end
           end
        end
        local rewards =  self._surveyDojo.rewards
        if rewards and #rewards > 0 then
            KTool.SetActive(self.RewardGroup.gameObject,true)
        end
        if checkInt(jsonData.drawId) > 0 then
            local vo = CardConfMgr:GetInstance():GetCardByRefId(jsonData.drawId)
            self.BossDrawingNode:Execute(vo.defaultSkin)
            KTool.SetActive(self.BossDrawingNode.gameObject , true)
        else 
            KTool.SetActive(self.BossDrawingNode.gameObject , false)
        end
        self:FillSurvey()
    end)
end

function UIActivitySkipUrlNode:DrawReards()
    GameUtils.Request(Interfaces.WebLinkDraw, {activityUuid = self._data.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local redPoint =  self.BtnLeavefor.transform:Find("redPoint")
        KTool.SetActive(redPoint, false)
        ActivityUtils.UpdateActivityMainRedPointState(self._data.id,  -1)
        self._surveyDojo.submitted = 1
        local UIModule = CS.Engine.UI.UIModule
        local jsonData = response.data
        if #jsonData.rewards > 0 then
            GoodsUtils.DrawRewards(jsonData.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })     
        else 
            GameUtils.Toast(localize("奖励已发送至邮箱"))
        end
        self:RefreshContent()
    end)
end

--绘制问卷
function UIActivitySkipUrlNode:FillSurvey()
    if not self._surveyDojo then
        return
    end
    self:FillRewards(self._surveyDojo.rewards)
end

--奖励
function UIActivitySkipUrlNode:FillRewards(rewards)
    if not rewards then
        return
    end

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsListNode)
    if not scr then
        return
    end
    scr:FreshBaseUI(rewards, false)
    if self._surveyDojo.submitted == 1 then
        scr:SetIsGetMaskShow(true)    
    end
end

function UIActivitySkipUrlNode:OnClick()
    if not self._surveyDojo then
        GameUtils.Toast(localize("活动不存在"))
        return
    elseif self._data.closeTime <= os.time() then
        GameUtils.Toast(localize("活动已过期"))
        return
    end
    xTry(function()
        local isOther = 1
        if UIModule.CurrentScreen then
            local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIActivityMainDialog)
            if dialog and dialog.Env and dialog.Env._displayType ~= nil then
                isOther = 0
                ---社群类型
                xRecord.record('6-010', string.format("click_community_enter_%d", checkInt(self._data.id)))
            end
        end
        if isOther == 1 then
            xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._data.id)))
        end
    end)
    CfUtils.WriteLocalData("WebLink" .. self._data.id , "1")
    --local redPoint =  self.BtnLeavefor.transform:Find("redPoint")
    --if isNotNull(redPoint) then
    --    KTool.SetActive(redPoint, false)
    --    ActivityUtils.UpdateActivityMainRedPointState(self._data.id,  -1)
    --end
    ---@type SDKService
    local SDKService = import('Game.Entry.SDKService')
    if SDKService:GetInstance():IsCommonSDK() then
        ---@type UserComponent
        local userComponent =  GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        if  isNotNull(userComponent) then
            local url = self._surveyDojo.url
            url = string.gsub(url, "{$accessToken}", userComponent.userInfo.access_token)
            CfUtils.OpenURL(url)
        end
    else
        local url = string.gsub(self._surveyDojo.url, "{$accessToken}", "")
        CfUtils.OpenURL(url)
    end
    if checkInt(self._surveyDojo.canDraw) <= 0 then
        return
    end
    if checkInt(self._surveyDojo.submitted) > 0 then
        return
    end
    if self.co  then
        cs_coroutine.stop(self.co)
        self.co = nil 
    end
    self.co = cs_coroutine.start(function ()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
        self:DrawReards()
    end)
    
end

function UIActivitySkipUrlNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivitySkipUrlNode
